//! Exact owned notice DATA emitted by the SAME raw/macro/controller traversal.
//! Raw byte columns and nonphysical default locations are preserved; no native
//! decoded-span diagnostic is fabricated for a raw continuation-byte location.
use super::{original_current_location::OriginalCurrentLocation as Location,original_raw_inputs::OriginalRawNoticeSink,original_raw_frame::{OriginalRawNotice,OriginalRawNoticeSeverity},original_raw_points::OriginalRawPoint,original_lexical_frame::OriginalLexicalFrameIdentity};
use crate::macro_expansion::{OriginalMacroRows as Rows,OriginalMacroText as Text,OriginalMacroNoticeKind as MacroKind,original_format_using};
use dm_syntax::{SettingAdmission,SettingRootLease,Span,OriginalLexicalNoticePoint,numeric_form::OriginalNumberNotice};use std::io;
#[derive(Clone,Copy,Debug,Eq,PartialEq)]pub enum OriginalNoticeSeverity{Error,Warning,Hint}
/// Coordinate DATA only, never a source currentness/EOF/model witness.
#[derive(Clone,Copy,Debug)]pub enum OriginalNoticePlace{Default,Builtins,Actual{occurrence:usize,line:usize,column:usize,raw_span:Option<Span>}}
pub struct OriginalNoticeView<'a>{pub place:OriginalNoticePlace,pub severity:OriginalNoticeSeverity,pub error_type:Option<&'static str>,pub message:&'a str,pub notes:OriginalNoticeNotes<'a>}
pub struct OriginalNoticeNotes<'a>{rows:std::slice::Iter<'a,Note>}
impl<'a>Iterator for OriginalNoticeNotes<'a>{type Item=(OriginalNoticePlace,&'a str);fn next(&mut self)->Option<Self::Item>{self.rows.next().map(|row|(place(&row.location,None),row.message.as_str()))}}
struct Note{location:Location,message:Text}
struct Notice{location:Location,raw_span:Option<Span>,severity:OriginalNoticeSeverity,error_type:Option<&'static str>,message:Text,notes:Rows<Note>}
/// Payload rows and all nested text/frame handles precede their domain root.
/// No Clone permits duplicating row allocations under one reservation.
pub struct OriginalRichNotices{rows:Rows<Notice>,domain:SettingRootLease,failed:bool}
fn poll(a:&SettingAdmission<'_>)->io::Result<()>{a.checkpoint().map_err(|e|a.take_operational_error().unwrap_or(e))}
fn place(location:&Location,span:Option<Span>)->OriginalNoticePlace{match location{Location::Default=>OriginalNoticePlace::Default,Location::Builtins=>OriginalNoticePlace::Builtins,Location::Expansion(origin)=>OriginalNoticePlace::Actual{occurrence:origin.occurrence,line:origin.line,column:origin.byte_column.expect("checked actual expansion byte column"),raw_span:span},Location::Physical{occurrence,point,..}=>OriginalNoticePlace::Actual{occurrence:*occurrence,line:point.line,column:point.column,raw_span:span}}}
impl OriginalRichNotices{
 pub(super) fn new(a:&SettingAdmission<'_>)->io::Result<Self>{Ok(Self{rows:Rows::new(a)?,domain:a.reserve(0).map_err(|e|a.take_operational_error().unwrap_or(e))?,failed:false})}
 fn check(&mut self,a:&SettingAdmission<'_>)->io::Result<()>{if self.failed{return Err(io::ErrorKind::InvalidInput.into())}let result=if !a.matches_lease_domain(&self.domain){Err(io::ErrorKind::InvalidInput.into())}else{poll(a)};if result.is_err(){self.failed=true}result}
 pub fn iter(&self)->impl Iterator<Item=OriginalNoticeView<'_>>{self.rows.as_slice().iter().map(|row|OriginalNoticeView{place:place(&row.location,row.raw_span),severity:row.severity,error_type:row.error_type,message:row.message.as_str(),notes:OriginalNoticeNotes{rows:row.notes.as_slice().iter()}})}
 pub fn len(&self)->usize{self.rows.len()}pub fn is_empty(&self)->bool{self.rows.len()==0}
 pub(super) fn message_using(&mut self,location:Location,span:Option<Span>,severity:OriginalNoticeSeverity,error_type:Option<&'static str>,message:Text,a:&SettingAdmission<'_>)->io::Result<usize>{self.check(a)?;let result=(||{match &location{Location::Expansion(origin)if origin.byte_column.is_none()=>return Err(io::ErrorKind::InvalidInput.into()),Location::Physical{frame,..}if !frame.admitted_by(a)=>return Err(io::ErrorKind::InvalidInput.into()),_=>()};let index=self.rows.len();self.rows.push(Notice{location,raw_span:span,severity,error_type,message,notes:Rows::new(a)?},a)?;Ok(index)})();if result.is_err(){self.failed=true}result}
 pub(super) fn note_using(&mut self,at:usize,location:Location,message:Text,a:&SettingAdmission<'_>)->io::Result<()>{self.check(a)?;let result=(||{match &location{Location::Expansion(origin)if origin.byte_column.is_none()=>return Err(io::ErrorKind::InvalidInput.into()),Location::Physical{frame,..}if !frame.admitted_by(a)=>return Err(io::ErrorKind::InvalidInput.into()),_=>()};let notice=self.rows.as_mut_slice().get_mut(at).ok_or(io::ErrorKind::InvalidInput)?;notice.notes.push(Note{location,message},a)})();if result.is_err(){self.failed=true}result}
 pub(super) fn macro_using(&mut self,location:Location,kind:&MacroKind,a:&SettingAdmission<'_>)->io::Result<usize>{let mut text=Text::new(a)?;original_format_using(&mut text,a,|out|{use std::fmt::Write;match kind{MacroKind::WrongArity=>out.write_str("wrong number of arguments to macro call"),MacroKind::UnexpectedEof=>out.write_str("unexpected EOF"),MacroKind::DepthLimit(name)=>write!(out,"expanding {:?} would exceed max recursion depth of 32 levels",name.as_str()),MacroKind::StringifyNonArgument(name)=>write!(out,"can't stringify non-argument ident {:?}",name.as_str()),MacroKind::StringifyNonIdent(token)=>write!(out,"can't stringify non-ident '{}'",token.as_str()),MacroKind::StringifyEof=>out.write_str("can't stringify EOF")}})?;self.message_using(location,None,OriginalNoticeSeverity::Error,None,text,a)}
}
impl OriginalRawNoticeSink for OriginalRichNotices{
 fn lexical(&mut self,frame:&OriginalLexicalFrameIdentity,occurrence:usize,point:OriginalRawPoint,notice:OriginalRawNotice,a:&SettingAdmission<'_>)->io::Result<()>{self.check(a)?;let mut text=Text::new(a)?;original_format_using(&mut text,a,|out|notice.write_message(out))?;self.message_using(Location::Physical{frame:frame.clone(),occurrence,point},Some(notice.span),match notice.severity{OriginalRawNoticeSeverity::Error=>OriginalNoticeSeverity::Error,OriginalRawNoticeSeverity::Warning=>OriginalNoticeSeverity::Warning},notice.error_type,text,a)?;Ok(())}
 fn numeric(&mut self,frame:&OriginalLexicalFrameIdentity,occurrence:usize,point:OriginalRawPoint,_:OriginalLexicalNoticePoint,notice:OriginalNumberNotice<'_>,a:&SettingAdmission<'_>)->io::Result<()>{self.check(a)?;let severity=if notice.is_warning(){OriginalNoticeSeverity::Warning}else{OriginalNoticeSeverity::Error};let error_type=notice.error_type();let mut text=Text::new(a)?;original_format_using(&mut text,a,|out|notice.write_message(out))?;self.message_using(Location::Physical{frame:frame.clone(),occurrence,point},None,severity,error_type,text,a)?;Ok(())}
}
#[cfg(test)]mod tests{
 use super::*;use crate::{SourceProvider,SourceAcquisitionLease,InitialEnvironment};use std::{path::Path,sync::{Arc,atomic::{AtomicUsize,Ordering}}};
 struct File{raw:Vec<u8>,lease:SourceAcquisitionLease}
 impl File{fn new(raw:&[u8])->Self{Self{raw:raw.to_vec(),lease:SourceAcquisitionLease::from_raw_original_bytes(raw.to_vec(),17u64)}}}
 impl SourceProvider for File{fn initial_environment(&self)->InitialEnvironment{InitialEnvironment::OriginalChecker0290}fn read(&self,_:&Path)->Result<String,String>{panic!("notice owner must not prepare or reread text")}fn original_source_bytes<'a>(&'a self,lease:&'a SourceAcquisitionLease)->io::Result<Option<&'a[u8]>>{if !lease.same_original_acquisition(&self.lease){return Err(io::ErrorKind::InvalidInput.into())}Ok(Some(&self.raw))}}
 #[test]fn actual_raw_lexical_notice_retains_bom_adjusted_byte_column_and_actual_frame_after_pop(){
  let used=Arc::new(AtomicUsize::new(0));let a=SettingAdmission::new(&used,8<<20,&||Ok(()));let file=File::new(b"\xef\xbb\xbf\x01\n");let mut inputs=super::super::original_raw_inputs::OriginalRawInputs::new(&a).unwrap();inputs.push_opened(&file,file.lease.clone(),0,0,&a).unwrap();let mut notices=OriginalRichNotices::new(&a).unwrap();loop{match inputs.next_using(&file,&a,&mut notices).unwrap(){crate::macro_expansion::OriginalMacroRawStep::End=>break,_=>()}}assert_eq!(notices.len(),1);let notice=notices.iter().next().unwrap();assert_eq!(notice.message,"illegal byte 0x1");assert_eq!(notice.severity,OriginalNoticeSeverity::Error);assert!(matches!(notice.place,OriginalNoticePlace::Actual{occurrence:0,line:1,column:1,..}));drop(inputs);assert!(used.load(Ordering::Acquire)>0);drop(notices);assert_eq!(used.load(Ordering::Acquire),0);
 }
 #[test]fn actual_numeric_notice_keeps_warning_type_and_actual_eof_column_not_a_native_span(){
  let used=Arc::new(AtomicUsize::new(0));let a=SettingAdmission::new(&used,8<<20,&||Ok(()));let file=File::new(b"2147483649");let mut inputs=super::super::original_raw_inputs::OriginalRawInputs::new(&a).unwrap();inputs.push_opened(&file,file.lease.clone(),0,0,&a).unwrap();let mut notices=OriginalRichNotices::new(&a).unwrap();loop{match inputs.next_using(&file,&a,&mut notices).unwrap(){crate::macro_expansion::OriginalMacroRawStep::End=>break,_=>()}}assert_eq!(notices.len(),1);let notice=notices.iter().next().unwrap();assert_eq!(notice.severity,OriginalNoticeSeverity::Warning);assert_eq!(notice.error_type,Some("integer_precision_loss"));assert!(notice.message.starts_with("precision loss of integer constant:"));assert!(matches!(notice.place,OriginalNoticePlace::Actual{occurrence:0,column:10,raw_span:None,..}));drop((inputs,notices));assert_eq!(used.load(Ordering::Acquire),0);
 }
 #[test]fn builtin_note_is_distinct_from_default_and_neither_claims_a_physical_source(){
  let used=Arc::new(AtomicUsize::new(0));let a=SettingAdmission::new(&used,1<<20,&||Ok(()));let mut notices=OriginalRichNotices::new(&a).unwrap();let mut text=Text::new(&a).unwrap();text.push_str("macro redefined: TRUE",&a).unwrap();let at=notices.message_using(Location::Default,None,OriginalNoticeSeverity::Warning,Some("macro_redefined"),text,&a).unwrap();let mut text=Text::new(&a).unwrap();text.push_str("previous definition of TRUE",&a).unwrap();notices.note_using(at,Location::Builtins,text,&a).unwrap();let notice=notices.iter().next().unwrap();assert!(matches!(notice.place,OriginalNoticePlace::Default));let mut notes=notice.notes;let(point,message)=notes.next().unwrap();assert!(matches!(point,OriginalNoticePlace::Builtins));assert_eq!(message,"previous definition of TRUE");assert!(notes.next().is_none());drop(notes);drop(notices);assert_eq!(used.load(Ordering::Acquire),0);
 }
 #[test]fn default_location_stays_nonphysical_and_first_resource_failure_cannot_publish_a_notice(){
  let used=Arc::new(AtomicUsize::new(0));let a=SettingAdmission::new(&used,0,&||Ok(()));let mut notices=OriginalRichNotices::new(&a).unwrap();let failure=notices.macro_using(Location::Default,&MacroKind::WrongArity,&a).unwrap_err();assert_eq!(failure.kind(),io::ErrorKind::OutOfMemory);assert!(notices.is_empty());drop(notices);assert_eq!(used.load(Ordering::Acquire),0);
 }
}
